    seen = set()

    # Extend each diagonal endpoint of a same-color connected component along
    # its outward diagonal. Other colors act as blockers; only background cells
    # are filled.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            component = []
            q = deque([(r, c)])
            seen.add((r, c))
